def tri(n):
    if n < 0:
        return []

    sequence = []
    for i in range(n + 1):
        if i == 0:
            continue  # tri(1) is the first element (index 0 in the list)
        if i == 1:
            sequence.append(3)
        elif i == 2:
            sequence.append(1 + 2 / 2)
        else:
            if i % 2 == 0:
                sequence.append(1 + i / 2)
            else:
                prev1 = sequence[i - 2]
                prev2 = sequence[i - 1]
                next_val = sequence[i - 1] if i - 1 < len(sequence) else 1 + (i - 1) / 2
                sequence.append(prev1 + prev2 + next_val)

    return sequence
